using System;using System.Linq;using BeamScheduleFormatter;
class FinishQuantitiesTests {
 static int checks;static void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<1e-8,m);}static void Bad(Action a,string m){bool bad=false;try{a();}catch{bad=true;}Check(bad,m);}
 static void Main(){var w=new WallItem{Id="W1",Description="Wall",Length=5,Height=3,Quantity=1,BlockWidth=.4,BlockHeight=.2,Plaster="2 sides"};var d=new OpeningItem{Id="D1",Description="Door",Wall="W1",Material="Manual",Kind="Door",Width=1,Height=2,Quantity=1};d.Validate();var openings=new[]{d};var noTiles=new FinishItem[0];var p=PlasterTakeoff.Calculate(w,openings,noTiles);Near(p.Net,26,"Two sides without tile entry");Near(p.TileDeduction,0,"No phantom tile deduction");w.Plaster="1 side (A)";Near(PlasterTakeoff.Calculate(w,openings,noTiles).Net,13,"Single face plaster");var t=new FinishItem{Id="T1",Description="Bath tile",Code="WT-01",Category="Wall",Wall="w1",Kind="Tiles",Side="B",Basis="Dimensions",Length=2,Width=1.5,Quantity=2,Deduction=1};t.Validate();Near(t.Total(w,openings),5,"Partial finish total deduction once");Near(PlasterTakeoff.Calculate(w,openings,new[]{t}).Net,13,"Opposite face tile not deducted");t.Side="A";p=PlasterTakeoff.Calculate(w,openings,new[]{t});Near(p.Net,8,"Same face tile deducted once");Near(p.TileDeduction,5,"Actual linked tile area");w.Plaster="2 sides";t.Side="Both";Near(PlasterTakeoff.Calculate(w,openings,new[]{t}).Net,16,"Both tiled faces");Near(PlasterTakeoff.Calculate(w,openings,new[]{t},"None").Net,0,"Unpainted masonry option");var paint=new FinishItem{Id="P1",Description="Wall paint",Code="WP-01",Category="Wall",Wall="W1",Kind="Paint",Side="Both",Basis="Whole wall (auto)"};Near(paint.Total(w,openings,new[]{t,paint}),16,"Auto paint deducts tile faces");t.Side="A";Near(paint.Total(w,openings,new[]{t,paint}),21,"Asymmetric tile painting");t.Basis="Whole wall (auto)";Near(t.PerFace(w,openings),13,"Whole-wall tile automatically excludes doors");Near(PlasterTakeoff.Calculate(w,openings,new[]{t}).Net,13,"Full tile side leaves opposite plaster");var duplicate=new[]{t,t};Bad(()=>PlasterTakeoff.Calculate(w,openings,duplicate),"Excess tile area rejected");t.Basis="Dimensions";t.Deduction=100;Bad(()=>t.Validate(),"Over-deduction rejected");var ceiling=new FinishItem{Id="C1",Description="Ceiling",Code="CF-01",Category="Ceiling",Length=4,Width=3,Quantity=2,Deduction=2};Near(ceiling.Total(null,openings),22,"Ceiling deduction per entry");ceiling.Category="Floor";Near(ceiling.Total(null,openings),22,"Floor area");var d2=new OpeningItem{Wall="W1",Width=.5,Height=1,Quantity=1};var three=new[]{d,d2,d2};Near(w.Net(three),12,"Three openings allowed");Bad(()=>w.Net(new[]{d,d2,d2,d2}),"Fourth opening rejected");Check(w.Blocks(openings)==163,"Finishes do not reduce CHB blocks");Console.WriteLine("PASS: "+checks+" face-specific plaster/paint, optional tiles, finish areas, opening limit and deduction checks.");}
}
